function shapeNpcLine48(n,line,p,topic,attempt=0){
 let out=String(line||'').trim(),cad=n.cadence||'lowercase';
 if((cad==='rambling'||attempt>2)&&!n.short)out+=` ${NPC_SUFFIX48[(hash(n.handle+p.id+attempt)>>>2)%NPC_SUFFIX48.length]}`;
 if(cad==='proper')out=out.charAt(0).toUpperCase()+out.slice(1)+(/[.!?]$/.test(out)?'':'.');
 if(cad==='lowercase'||cad==='no-punctuation')out=out.toLowerCase();
 if(cad==='no-punctuation')out=out.replace(/[.!?]+$/g,'');
 if(cad==='punctuation'&&!/[!?]{2}$/.test(out))out+=n.personality==='chaotic'?'!!!':'??';
 if(cad==='emoji'&&n.signatureEmoji&&!out.includes(n.signatureEmoji))out+=` ${n.signatureEmoji}`;
 if(topic==='music'&&n.interests?.includes('charts')&&attempt%3===1)out+=` chart people are going to be unbearable about this`;
 if(topic==='fashion'&&n.interests?.includes('fashion')&&attempt%3===1)out+=` the styling crowd is already clocking it`;
 return out;
}
