 const bank=banks[career]||banks.Music,start=(cycle*3)%bank.length,stride=5;return [0,1,2].map((i)=>{const src=bank[(start+i*stride)%bank.length];return{id:`city48-${hash(city)}-${cycle}-${career.toLowerCase()}-${i}`,badge:`${tag} · ${src.kind}`,title:src.title,tease:small?src.tease:`${src.tease} The room is stronger now, and people will notice how you handle it.`,choices:src.choices}})
