function activeStory48(){let ops=cityStoryOps48(),city=state.player.city||'Los Angeles';if(ops.length&&ops.every(x=>state.storyDone.includes(x.id))){state.localStoryCycle48[city]=(Number(state.localStoryCycle48[city])||0)+1;ops=cityStoryOps48();baseSave48()}return ops.filter(x=>!state.storyDone.includes(x.id))}
function applyStory48(e={}){applyEffect(e)}
function storyOutcome48(op,label,e,outcome){const rewards=[],storyCash=economyMoney48(e.money);if(storyCash)rewards.push(`${storyCash>0?'+':''}${localMoney(storyCash)}`);if(e.followers)rewards.push(`+${fmt(e.followers)} followers`);if(e.fame)rewards.push(`+${e.fame} fame`);if(e.rep)rewards.push(`${e.rep>0?'+':''}${e.rep} rep`);if(e.xp)rewards.push(`+${e.xp} XP`);if(e.energy)rewards.push(`${e.energy>0?'+':''}${e.energy} energy`);if(e.gems)rewards.push(`+${e.gems} ◆`);modal.innerHTML=`<div class="outcomeoverlay"><div class="outcomecard"><div class="outcomehalo">✦</div><div class="eventtag">${esc(op.badge)}</div><h2>${esc(op.title)}</h2><p>${esc(outcome)}</p>${rewards.length?`<div class="rewardburst">${rewards.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}${e.gems?`<div class="outcomeripple">Chapter done. +${e.gems} diamond${e.gems===1?'':'s'} for you.</div>`:''}<button class="btn blue full" id="storycontinue">Continue</button></div></div>`;$('#storycontinue').onclick=()=>{closeModal();render()}}
function openStory48(id){const op=cityStoryOps48().find(x=>x.id===id);if(!op)return;showSheet(op.badge,`<div class="storyophero"><div class="eventtag">${esc(op.badge)}</div><h3>${esc(op.title)}</h3><p>${esc(op.tease)}</p></div><div class="heading">What do you do?</div>${op.choices.map((c,i)=>`<button class="eventchoice" data-story-choice="${i}"><span><b>${esc(c[0])}</b></span><em>›</em></button>`).join('')}`);modal.querySelectorAll('[data-story-choice]').forEach(b=>b.onclick=()=>{if(b.disabled)return;modal.querySelectorAll('[data-story-choice]').forEach(x=>x.disabled=true);const c=op.choices[+b.dataset.storyChoice],e={...(c[1]||{})};applyStory48(e);if(!state.storyDone.includes(op.id))state.storyDone.push(op.id);state.storyHistory.unshift({id:op.id,title:op.title,choice:c[0],outcome:c[2],city:state.player.city,at:now()});const localDone=cityStoryOps48().filter(x=>state.storyDone.includes(x.id)).length;if(localDone===3){state.player.gems=(state.player.gems||0)+1;e.gems=(e.gems||0)+1;addNotif(`${state.player.city} story set complete · +1 diamond.`,'career')}remember('story_choice',{title:op.title,choice:c[0],outcome:c[2],effect:e,city:state.player.city,visibility:'public'});state.events.unshift(`${op.title}: ${c[0]}`);if(globalThis.SCENE_advanceDay)globalThis.SCENE_advanceDay({kind:'story',title:op.title,choice:c[0],outcome:c[2],city:state.player.city});addNotif(`${op.badge||'Story'} · ${[e.followers?`+${fmt(e.followers)} followers`:'',e.fame?`+${e.fame} fame`:'',e.rep?`${e.rep>0?'+':''}${e.rep} rep`:''].filter(Boolean).join(' · ')||'done'}.`,'career');save();storyOutcome48(op,c[0],e,c[2])})}

