function choiceFlavor48(c){if(c[2])return c[2];const t=String(c[0]||'').toLowerCase();if(/joke|laugh|funny|playful/.test(t))return 'control the tone';if(/ask|question|negotiate|talk|what they want/.test(t))return 'read the room';if(/post|share|tease|clip|audience|chat/.test(t))return 'feed the moment';if(/rewrite|blend|improvise|different|change|stranger|weird/.test(t))return 'make it yours';if(/stay|keep|protect|ignore|wait|safe/.test(t))return 'hold your nerve';if(/go|push|commit|trust|follow|wear|take/.test(t))return 'back the instinct';const flavors=['make the room react','play the long game','keep some mystery','change the temperature','bet on yourself','leave them talking'];return flavors[Math.abs(hash(String(c[0]||'')))%flavors.length]}
