function resourcesPanel48(){return `<div class="resource48grid"><div class="resource48"><span class="resourceicon48 energy">${resourceIcon48('energy')}</span><strong>Recharge</strong><p>Free +20 energy every 20 minutes.</p><button class="btn secondary" data-action="rest">Rest</button></div><div class="resource48"><span class="resourceicon48 pr">${resourceIcon48('pr')}</span><strong>PR push · ◆1</strong><p>Push your name beyond your current audience.</p><button class="btn" data-action="boost">Boost</button></div><div class="resource48"><span class="resourceicon48 energy">${resourceIcon48('energy')}</span><strong>Energy pack · ◆1</strong><p>Instant +45 energy.</p><button class="btn" data-v48-resource="energy">Use</button></div><div class="resource48"><span class="resourceicon48 spotlight">${resourceIcon48('spotlight')}</span><strong>Spotlight · ◆2</strong><p>Give your latest post a stronger 30-minute discovery window.</p><button class="btn" data-v48-resource="spotlight">Push</button></div><div class="resource48 viralresource"><span class="resourceicon48 viral">${resourceIcon48('viral')}</span><strong>Viral push · ◆4</strong><p>Turn your latest post into a real algorithm moment. Views, likes, replies and press can cascade from it.</p><button class="btn blue" data-v48-resource="viral">Go viral</button></div><div class="resource48 vip48"><span class="resourceicon48 vip">${resourceIcon48('vip')}</span><strong>VIP access · ◆3</strong><p>Force a premium invite, private room or high-value social opportunity into your story.</p><button class="btn blue" data-v48-resource="vip">Unlock VIP</button></div></div>`}
renderWorld=function(){
 const view=state.careerView||'story';return `<section class="section career48"><div class="sectiontop"><div><div class="kicker">Career</div><h2>Your story.</h2></div><div class="skillchip">${esc(LADDER48[rank48()].name)}</div></div><div class="career48tabs"><button class="${view==='story'?'on':''}" data-career-view="story">My story</button><button class="${view==='work'?'on':''}" data-career-view="work">Opportunities</button><button class="${view==='travel'?'on':''}" data-career-view="travel">Travel</button><button class="${view==='resources'?'on':''}" data-career-view="resources">Resources</button></div>${view==='story'?storyPanel48():view==='work'?`<div class="careerpanelintro"><strong>Opportunities · ${esc(state.player.city)}</strong><span>Better rooms unlock as your social ladder rises.</span></div><div class="jobboard">${jobCards48()}</div>`:view==='travel'?travelPanel48():resourcesPanel48()}</section>`;
};

function spendResource48(kind){const p=state.player,latest=playerPosts()[0];const cost={energy:1,spotlight:2,viral:4,vip:3}[kind]||0;if((p.gems||0)<cost)return flash(`You need ${cost} diamonds.`);if((kind==='spotlight'||kind==='viral')&&!latest)return flash('Post something first.');p.gems-=cost;if(kind==='energy'){p.energy=clamp(p.energy+45);remember('resource',{kind});save();render();return flash('+45 energy')}
 if(kind==='spotlight'){latest.virality=(latest.virality||1)+1.8;latest.seedViews=Math.max(latest.seedViews||0,Math.round(Math.max(50,p.followers*.55)));remember('spotlight',{postId:latest.id});}
 if(kind==='viral'){latest.virality=(latest.virality||1)+5;latest.seedViews=Math.max(latest.seedViews||0,Math.round(Math.max(800,p.followers*4.5)));latest.seedLikes=Math.max(latest.seedLikes||0,Math.round(Math.max(45,p.followers*.16)));for(let i=0;i<Math.min(10,4+Math.floor(p.fame/30));i++){const c=contextualFanComment(latest);if(c)latest.comments.push(c)}p.fame+=Math.max(2,Math.min(8,2+Math.floor(p.fame/50)));const fol227=p.followers;p.followers+=Math.max(80,Math.round(p.followers*.08));remember('viral_push',{postId:latest.id,text:latest.text});try{globalThis.SCENE_VIRAL227?.fromPush(latest,p.followers-fol227)}catch{}setTimeout(()=>maybePublicEcho(),100)}
 if(kind==='vip'){state.pendingEvent={badge:'VIP ACCESS',title:pick(['A table opens at a private industry dinner','A stylist texts you a front-row seat','A famous afterparty suddenly has your name','A private listening room asks if you are coming']),body:'This invitation did not exist ten minutes ago. Now it does.',choices:[['Go and work the room',{energy:-9,fame:6,followers:Math.max(80,Math.round(p.followers*.04)),xp:16},'You leave with more people knowing your name than when you walked in.'],['Go — but keep the night private',{energy:-6,rep:5,xp:14},'The access becomes a relationship, not a post.'],['Make one unforgettable entrance',{energy:-10,fame:8,followers:Math.max(120,Math.round(p.followers*.06))},'The entrance becomes the story.']]};remember('vip_access',{title:state.pendingEvent.title})}
 save();render();flash(kind==='viral'?'🔥 Your post is moving':kind==='vip'?'VIP opportunity unlocked':'Resource activated')}

/* ---------- Travel override with home + currency ---------- */
function flightBaseUsd48(origin,destination){if(destination===state.homeCity)return Math.max(220,CITY48[origin]?.flightUSD||650);if(origin===state.homeCity)return Math.max(220,CITY48[destination]?.flightUSD||650);return Math.max(220,Math.round(((CITY48[origin]?.flightUSD||650)+(CITY48[destination]?.flightUSD||650))*.62))}
travel=function(city){const dest=CITY48[city];if(!dest||city===state.player.city)return;const origin=state.player.city,base=flightBaseUsd48(origin,city),privateUnlocked=rank48()>=6||state.player.fame>=190,goingHome=city===state.homeCity,standard=goingHome?`<button class="travelmode standby" data-v48-flight="home"><span><b>Fly home</b><small>Always free · -8 energy · economy</small></span><strong>FREE</strong></button>`:`<button class="travelmode" data-v48-flight="economy"><span><b>Economy commercial</b><small>Cheapest · -8 energy · low visibility</small></span><strong>${localMoney(base)}</strong></button>`;showSheet(goingHome?'Fly home to Los Angeles':`Fly to ${city}`,`<div class="travelhero"><div class="eventtag">${esc(origin.toUpperCase())} → ${esc(city.toUpperCase())}</div><h3>${esc(city)}</h3><p>${esc(dest.country)} · ${goingHome?'Getting back to your LA home never costs cash.':'Your cash stays in USD wherever you travel. No exchange wallet, no conversion.'}</p></div>${standard}<button class="travelmode" data-v48-flight="business"><span><b>Business class</b><small>-2 energy · lounge visibility</small></span><strong>${localMoney(Math.round(base*2.2))}</strong></button><button class="travelmode ${privateUnlocked?'':'locked'}" data-v48-flight="private" ${privateUnlocked?'':'disabled'}><span><b>Private charter ${privateUnlocked?'':'· locked'}</b><small>${privateUnlocked?'No queues · +5 energy · paparazzi interest':'Unlock at A-List'}</small></span><strong>${privateUnlocked?localMoney(Math.round(base*8.5)):'♛'}</strong></button>`);modal.querySelectorAll('[data-v48-flight]').forEach(b=>b.onclick=()=>completeTravel48(city,b.dataset.v48Flight,origin))};
function completeTravel48(city,mode,origin){const freeHome=mode==='home'&&city===state.homeCity,mult=mode==='private'?8.5:mode==='business'?2.2:1,costUsd=freeHome?0:Math.round(flightBaseUsd48(origin,city)*mult),p=state.player,originShown=freeHome?'FREE':localMoney(costUsd);if(!freeHome&&!chargeUsd48(costUsd))return flash('You cannot afford this flight yet.');p.city=city;state.travelWallet=null;p.energy=clamp(p.energy+(mode==='private'?5:mode==='business'?-2:-8));p.xp+=mode==='private'?8:mode==='business'?5:3;state.travelHistory=state.travelHistory||[];state.travelHistory.unshift({city,mode,at:now(),costUsd,from:origin});let spotted=false;if(p.fame>=45&&Math.random()<Math.min(.82,.18+p.fame/320+(mode==='private'?.18:0))){spotted=true;const outlet=choosePlayerOutlet48('travel');if(outlet){/* Director records the witnessed arrival below; no instant article. */}}remember('travel',{city,mode,costUsd,from:origin,witnessed:spotted});save();const cash=`${currentCashLabel48()} USD`;modal.innerHTML=`<div class="outcomeoverlay"><div class="outcomecard"><div class="outcomehalo">✈</div><div class="eventtag">ARRIVAL</div><h2>${esc(city)}</h2><p>${freeHome?'You are home in Los Angeles. The trip back never costs you cash.':spotted?'You made it through arrivals — but not unnoticed.':'You landed without a scene. For now.'}</p><div class="rewardburst"><span>${freeHome?'FREE HOME FLIGHT':`-${esc(originShown)}`}</span><span>${mode==='private'?'+5':mode==='business'?'-2':'-8'} energy</span></div><div class="outcomeripple">You still have ${esc(cash)}. The same USD balance follows you everywhere.</div><button class="btn blue full" id="travelcontinue">Continue</button></div></div>`;$('#travelcontinue').onclick=()=>{closeModal();state.careerView='story';render()}}

/* ---------- You page + player archive ---------- */
renderYou=function(){const p=state.player,posts=playerPosts(),cash=currentCashLabel48();return `<section class="youpage"><div class="youhead"><div class="youidentity">${playerAvatarMarkup('youavatar')}<div class="youstats"><div><b>${posts.length}</b><span>Posts</span></div><div><b>${fmt(p.followers)}</b><span>Followers</span></div><div><b>${fmt(playerFollowingCount())}</b><span>Following</span></div></div></div><div class="youname"><strong>${esc(p.name)} ${p.verified?check():''}</strong><span>@${esc(p.handle)}</span></div><div class="youbio">${p.bio?esc(p.bio):'<span class="bioempty">Add a bio so this actually feels like your page.</span>'}</div><div class="youmeta">${esc(p.career)} · ${esc(p.city)} · Level ${lvl()} · ${fameTier(p.fame)}</div><div class="youbuttons"><button class="btn secondary" data-action="editprofile">Edit profile</button><button class="btn secondary" data-action="compose">New post</button></div></div><div class="youquick"><div><span>Fame</span><b>${p.fame}</b></div><div><span>Reputation</span><b>${p.reputation}</b></div><div><span>Cash · USD</span><b>${cash}</b></div><div><span>Energy</span><b>${p.energy}</b></div></div><div class="youposttabs"><button class="on">POSTS <span>${posts.length}</span></button></div>${posts.length?`<div class="youfeed">${posts.map(p=>postHtml(p,true)).join('')}</div>`:'<div class="empty youempty">No posts yet. Your profile starts looking alive as soon as you post.</div>'}</section>`};
