/* ---------- Media profile history ---------- */
const baseHistory48=historyPosts;
historyPosts=function(a){if(a.type!=='media')return baseHistory48(a);const existing=state.posts.filter(p=>p.authorId===a.id).sort((x,y)=>y.createdAt-x.createdAt);const bank={popbase:['A surprise interaction has pop fans doing detective work again.','One tiny update. Thousands of theories.','A new name is starting to circulate across entertainment timelines.'],bbcnews:['News, analysis and updates from around the world.','A developing story is drawing wider international attention.','Latest reporting and verified updates.'],skynews:['Breaking news and live updates as stories develop.','A major story is developing with more details expected.','Latest reporting from our newsroom.']}[a.id];if(bank&&existing.length<6){for(let i=existing.length;i<6;i++){const p=mkPost(a,180+i*260,bank[i%bank.length],{media:false,kind:'profile-history'});state.posts.push(p)}}return state.posts.filter(p=>p.authorId===a.id).sort((x,y)=>y.createdAt-x.createdAt).slice(0,12)};

/* ---------- Cleanup old template exposure ---------- */
function staleNpcLine48(text,parent=''){const t=String(text||'').trim().toLowerCase(),p=String(parent||'').trim().toLowerCase();if(!t)return true;if(/the way you just said|and left 😭|okay\?\?\?|this feels weirdly specific|definitely a story behind this|i need context because this sentence|the casual update i needed|why is this actually relatable/.test(t))return true;if(p&&p.length>20&&t.includes(p.slice(0,Math.min(42,p.length))))return true;return false}
function cleanThread48(p){const seen=new Set(),clean=[];for(const original of p.comments||[]){let c=original;const isPlayer=c.authorId==='player',isVerified=Boolean(c.authorId&&byId(c.authorId));if(!isPlayer&&!isVerified&&staleNpcLine48(c.text,p.text))c=contextualFanComment({...p,comments:clean});const k=String(c.text||'').trim().toLowerCase();if(k&&seen.has(k))continue;if(k)seen.add(k);if(c.replies){const rs=[],rseen=new Set();for(let r of c.replies){const verifiedReply=Boolean(r.authorId&&byId(r.authorId)),playerReply=r.authorId==='player';if(!verifiedReply&&!playerReply&&staleNpcLine48(r.text,c.text))r=contextualFanComment({...p,comments:[...clean,c,...rs]});const rk=String(r.text||'').trim().toLowerCase();if(rk&&rseen.has(rk))continue;if(rk)rseen.add(rk);rs.push(r)}c.replies=rs}clean.push(c)}p.comments=clean}
function migrate48(){if((state.livingWorldVersion||0)>=WORLD48)return;state.livingWorldVersion=WORLD48;state.homeCity='Los Angeles';state.careerView='story';const seenPosts=new Set(),kept=[];for(const p of state.posts||[]){let text=String(p.text||'');const src=String(p.sourceName||'').toLowerCase();if(p.liveNews&&['variety','people','enews','tmz','billboard','rollingstone','vogue'].includes(p.authorId)&&src&&!/(variety|people|e!|tmz|billboard|rolling stone|vogue|hollywood|deadline|entertainment|music|fashion|celebrity)/i.test(src)){p.authorId=/sky/i.test(src)?'skynews':'bbcnews';p.socialLabel='NEWS'}if(/A verified interaction involving .+ is driving fresh attention to their profile\.?/i.test(text)){const a=byId(p.authorId)||byId('popbase');text=media48Line(a?.type==='media'?a:byId('popbase'),'a public interaction that suddenly sent people searching their name');p.text=text;p.socialLabel='WHO IS THIS?'}if(/just hit another early-career milestone:/i.test(text)){const a=byId(p.authorId)||byId('variety');p.text=media48Line(a?.type==='media'?a:byId('variety'),'an early career move that is making industry people look twice')}if(/is getting noticed after a (solid|standout|viral|rough) showing/i.test(text)){const a=byId(p.authorId)||byId('variety');p.text=media48Line(a?.type==='media'?a:byId('variety'),'a recent booking that put the newcomer into a few unexpected conversations')}cleanThread48(p);const author48=byId(p.authorId),aboutPlayer=author48?.type==='media'&&String(p.text||'').toLowerCase().includes(String(state.player?.name||'').toLowerCase());if(aboutPlayer){const protectedThreads=(p.comments||[]).filter(c=>c.authorId==='player'||(c.authorId&&byId(c.authorId)?.type==='celeb')||(c.replies||[]).some(r=>r.authorId==='player'));p.comments=protectedThreads;const target=Math.min(8,Math.max(5,3+Math.floor((state.player?.fame||0)/35)));for(let guard=0;p.comments.length<target&&guard++<40;){const c=contextualFanComment(p);if(!c)break;p.comments.push(c)}}const sig=`${p.authorId}|${String(p.text||'').trim().toLowerCase()}`;if(seenPosts.has(sig)&&p.authorId!=='player')continue;seenPosts.add(sig);kept.push(p)}state.posts=kept;save()}
migrate48();

